import React, { useState } from 'react';
import { Form, Input, Button, Progress, Typography, Card, message } from 'antd';
import { LockOutlined, MailOutlined } from '@ant-design/icons';
import { supabase } from '../../config/supabase';

import { Typography } from 'antd'; // I removed the previous useTheme import using this replacement strategy

const { Title, Text } = Typography;
const { Link: TextLink } = Typography;

const AuthForm: React.FC = () => {
  const [isSignUp, setIsSignUp] = useState(false);
  const [loading, setLoading] = useState(false);
  const [form] = Form.useForm();
  const [passwordStrength, setPasswordStrength] = useState(0);

  const calculatePasswordStrength = (password: string) => {
    let strength = 0;
    if (password.length >= 8) strength++;
    if (password.length >= 12) strength++;
    if (/[a-z]/.test(password) && /[A-Z]/.test(password)) strength++;
    if (/\d/.test(password)) strength++;
    if (/[!@#$%^&*(),.?":{}|<>]/.test(password)) strength++;
    return strength;
  };

  const onValuesChange = (changedValues: any) => {
    if (changedValues.password && isSignUp) {
      setPasswordStrength(calculatePasswordStrength(changedValues.password));
    }
  };

  const handleSubmit = async (values: any) => {
    setLoading(true);
    try {
      if (isSignUp) {
        const { data, error } = await supabase.auth.signUp({
          email: values.email,
          password: values.password,
        });
        if (error) throw error;

        if (data.session) {
          message.success('Account created successfully!');
          // AuthProvider will handle the redirect
        } else {
          message.success('Account created! Please check your email to verify.');
          setIsSignUp(false);
        }
      } else {
        const { error } = await supabase.auth.signInWithPassword({
          email: values.email,
          password: values.password,
        });
        if (error) throw error;
        message.success('Successfully logged in!');
      }
    } catch (error: any) {
      message.error(error.message || 'Authentication failed');
    } finally {
      setLoading(false);
    }
  };

  const getStrengthColor = () => {
    if (passwordStrength <= 1) return 'exception';
    if (passwordStrength <= 3) return 'warning';
    return 'success';
  };

  return (
    <Card
      className="w-full max-w-md shadow-2xl rounded-2xl border-0"
      style={{ background: 'rgba(255, 255, 255, 0.95)', backdropFilter: 'blur(10px)' }}
    >
      <div className="text-center mb-8">
        <Title level={2} style={{ color: '#005BBB', marginBottom: 0 }}>
          {isSignUp ? 'Create Account' : 'Welcome Back'}
        </Title>
        <Text type="secondary">
          {isSignUp ? 'Sign up to get started' : 'Sign in to your account'}
        </Text>
      </div>

      <Form
        form={form}
        name="auth_form"
        onFinish={handleSubmit}
        layout="vertical"
        size="large"
        onValuesChange={onValuesChange}
        requiredMark={false}
      >
        <Form.Item
          name="email"
          label="Email Address"
          rules={[
            { required: true, message: 'Please input your email!' },
            { type: 'email', message: 'Please enter a valid email!' },
          ]}
        >
          <Input
            prefix={<MailOutlined className="text-gray-400" />}
            placeholder="you@example.com"
            className="rounded-lg"
          />
        </Form.Item>

        <Form.Item
          name="password"
          label="Password"
          rules={[
            { required: true, message: 'Please input your password!' },
            isSignUp ? { min: 8, message: 'Password must be at least 8 characters!' } : {},
            isSignUp ? { pattern: /[A-Z]/, message: 'Must contain uppercase letter!' } : {},
            isSignUp ? { pattern: /[a-z]/, message: 'Must contain lowercase letter!' } : {},
            isSignUp ? { pattern: /[0-9]/, message: 'Must contain number!' } : {},
          ]}
        >
          <Input.Password
            prefix={<LockOutlined className="text-gray-400" />}
            placeholder="••••••••"
            className="rounded-lg"
          />
        </Form.Item>

        {isSignUp && (
          <div className="mb-6">
            <div className="flex justify-between mb-1">
              <Text type="secondary" style={{ fontSize: '12px' }}>Password Strength</Text>
            </div>
            <Progress
              percent={(passwordStrength / 5) * 100}
              showInfo={false}
              status={getStrengthColor() as "success" | "exception" | "normal" | "active"}
              size="small"
              strokeLinecap="round"
            />
          </div>
        )}

        {isSignUp && (
          <Form.Item
            name="confirmPassword"
            label="Confirm Password"
            dependencies={['password']}
            hasFeedback
            rules={[
              { required: true, message: 'Please confirm your password!' },
              ({ getFieldValue }) => ({
                validator(_, value) {
                  if (!value || getFieldValue('password') === value) {
                    return Promise.resolve();
                  }
                  return Promise.reject(new Error('The two passwords that you entered do not match!'));
                },
              }),
            ]}
          >
            <Input.Password
              prefix={<LockOutlined className="text-gray-400" />}
              placeholder="••••••••"
              className="rounded-lg"
            />
          </Form.Item>
        )}

        <Form.Item>
          <Button
            type="primary"
            htmlType="submit"
            block
            size="large"
            loading={loading}
            className="bg-blue-600 hover:bg-blue-700 h-12 rounded-lg font-semibold text-lg shadow-md hover:shadow-lg transition-all"
          >
            {isSignUp ? 'Create Account' : 'Sign In'}
          </Button>
        </Form.Item>
      </Form>

      <div className="text-center mt-4">
        <TextLink
          onClick={() => {
            setIsSignUp(!isSignUp);
            form.resetFields();
            setPasswordStrength(0);
          }}
          className="text-blue-600 hover:text-blue-800 font-medium"
        >
          {isSignUp ? 'Already have an account? Sign In' : "Don't have an account? Sign Up"}
        </TextLink>
      </div>
    </Card>
  );
};

export default AuthForm;

import React, { createContext, useContext, useEffect, useState } from 'react';
import { supabase, User } from '../config/supabase';
import { Session } from '@supabase/supabase-js';

interface AuthContextType {
    user: User | null;
    session: Session | null;
    loading: boolean;
    signOut: () => Promise<void>;
}

const AuthContext = createContext<AuthContextType>({
    user: null,
    session: null,
    loading: true,
    signOut: async () => { },
});

export const useAuth = () => useContext(AuthContext);

export const AuthProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
    const [user, setUser] = useState<User | null>(null);
    const [session, setSession] = useState<Session | null>(null);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        // Get initial session
        supabase.auth.getSession().then(({ data: { session } }) => {
            setSession(session);
            setUser(session?.user ? {
                id: session.user.id,
                email: session.user.email!,
                name: session.user.user_metadata.name || session.user.email!.split('@')[0],
                created_at: session.user.created_at
            } : null);
            setLoading(false);
        }).catch((error) => {
            console.error('Auth check failed:', error);
            setLoading(false);
        });

        // Listen for auth changes
        const {
            data: { subscription },
        } = supabase.auth.onAuthStateChange((_event, session) => {
            setSession(session);
            setUser(session?.user ? {
                id: session.user.id,
                email: session.user.email!,
                name: session.user.user_metadata.name || session.user.email!.split('@')[0],
                created_at: session.user.created_at
            } : null);
            setLoading(false);
        });

        return () => subscription.unsubscribe();
    }, []);

    const signOut = async () => {
        await supabase.auth.signOut();
    };

    return (
        <AuthContext.Provider value={{ user, session, loading, signOut }}>
            {!loading && children}
        </AuthContext.Provider>
    );
};

import React, { createContext, useContext, useEffect, useState } from 'react';

type Theme = 'light' | 'dark';

interface ThemeContextType {
    theme: Theme;
    toggleTheme: () => void;
    isDarkMode: boolean;
}

const ThemeContext = createContext<ThemeContextType | undefined>(undefined);

export const ThemeProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
    const [theme, setTheme] = useState<Theme>(() => {
        const savedTheme = localStorage.getItem('theme');
        return (savedTheme as Theme) || 'light';
    });

    useEffect(() => {
        localStorage.setItem('theme', theme);
        if (theme === 'dark') {
            document.documentElement.classList.add('dark');
        } else {
            document.documentElement.classList.remove('dark');
        }
    }, [theme]);

    const toggleTheme = () => {
        setTheme((prev) => (prev === 'light' ? 'dark' : 'light'));
    };

    return (
        <ThemeContext.Provider value={{ theme, toggleTheme, isDarkMode: theme === 'dark' }}>
            {children}
        </ThemeContext.Provider>
    );
};

export const useTheme = () => {
    const context = useContext(ThemeContext);
    if (context === undefined) {
        throw new Error('useTheme must be used within a ThemeProvider');
    }
    return context;
};

import { StrictMode } from 'react';
import { createRoot } from 'react-dom/client';
import { ConfigProvider, theme } from 'antd';
import App from './App.tsx';
import './index.css';
import { ThemeProvider, useTheme } from './contexts/ThemeContext';

const Main = () => {
  const { isDarkMode } = useTheme();

  return (
    <ConfigProvider
      theme={{
        algorithm: isDarkMode ? theme.darkAlgorithm : theme.defaultAlgorithm,
        token: {
          colorPrimary: '#1890ff',
          fontFamily: "'Inter', sans-serif",
          borderRadius: 8,
        },
      }}
    >
      <App />
    </ConfigProvider>
  );
};

createRoot(document.getElementById('root')!).render(
  <StrictMode>
    <ThemeProvider>
      <Main />
    </ThemeProvider>
  </StrictMode>
);

import React, { useState } from 'react';
import { Card, Select, Button, Typography, Row, Col, Statistic, Tag, List, Alert, Space, Upload, message, Tabs } from 'antd';
import { SafetyCertificateOutlined, CheckCircleOutlined, WarningOutlined, CloseCircleOutlined, UploadOutlined, FileZipOutlined } from '@ant-design/icons';
import { API_ENDPOINTS } from '../../../config/api';
import { useTheme } from '../../../contexts/ThemeContext';

const { Paragraph, Text, Title } = Typography;
const { Dragger } = Upload;

const ComplianceChecker: React.FC = () => {
    const [selectedStandards, setSelectedStandards] = useState<string[]>(['NIST', 'GDPR', 'AWS CIS', 'PCI DSS', 'HIPAA']);
    const [zipBase64, setZipBase64] = useState<string | null>(null);
    const [results, setResults] = useState<any>(null);
    const [loading, setLoading] = useState(false);
    const [fileName, setFileName] = useState<string>('');

    const handleFileUpload = (info: any) => {
        const file = info.file;
        setFileName(file.name);
        const reader = new FileReader();
        reader.readAsDataURL(file as Blob);
        reader.onload = () => {
            const base64 = (reader.result as string).split(',')[1];
            setZipBase64(base64);
            message.success(`${file.name} file uploaded successfully`);
        };
        reader.onerror = (error) => {
            console.error('Error reading zip file:', error);
            message.error('Failed to read zip file');
        };
        return false; // Prevent auto-upload
    };

    const handleCheck = async () => {
        if (!zipBase64 || selectedStandards.length === 0) {
            message.warning('Please upload a ZIP file and select at least one standard.');
            return;
        }
        setLoading(true);
        setResults(null);
        try {
            const response = await fetch(API_ENDPOINTS.COMPLIANCE_CHECKER, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    zip_file: zipBase64,
                    standards: selectedStandards
                }),
            });
            const data = await response.json();
            if (data.compliance_report) {
                setResults(data.compliance_report);
                message.success('Compliance analysis complete!');
            } else {
                message.error(data.error || 'Failed to analyze compliance.');
            }
        } catch (error) {
            console.error(error);
            message.error('Connection error. Please try again.');
        } finally {
            setLoading(false);
        }
    };

    const renderStandardReport = (standardName: string, data: any) => {
        const passed = data?.passed?.length || 0;
        const failed = data?.violations?.length || 0;
        const total = passed + failed;
        const score = total > 0 ? Math.round((passed / total) * 100) : 0;

        return (
            <Space direction="vertical" size="large" style={{ width: '100%' }}>
                <Row gutter={16}>
                    <Col span={8}>
                        <Card size="small">
                            <Statistic title="Module Score" value={score} suffix="%" valueStyle={{ color: score > 80 ? '#3f8600' : '#cf1322' }} prefix={<SafetyCertificateOutlined />} />
                        </Card>
                    </Col>
                    <Col span={8}>
                        <Card size="small">
                            <Statistic title="Passed" value={passed} valueStyle={{ color: '#3f8600' }} prefix={<CheckCircleOutlined />} />
                        </Card>
                    </Col>
                    <Col span={8}>
                        <Card size="small">
                            <Statistic title="Violations" value={failed} valueStyle={{ color: '#cf1322' }} prefix={<CloseCircleOutlined />} />
                        </Card>
                    </Col>
                </Row>

                {data?.violations?.length > 0 ? (
                    <Card title="Detected Violations" size="small" className="border-red-100">
                        <List
                            itemLayout="vertical"
                            dataSource={data.violations}
                            renderItem={(item: any) => (
                                <List.Item>
                                    <List.Item.Meta
                                        avatar={<CloseCircleOutlined className="text-red-500" />}
                                        title={<Text strong>{item.resource || 'Infrastructure Resource'}</Text>}
                                        description={
                                            <Space direction="vertical" style={{ width: '100%' }}>
                                                <Text>{item.description}</Text>
                                                {item.remediation && (
                                                    <Alert
                                                        message="Remediation Path"
                                                        description={item.remediation}
                                                        type="warning"
                                                        showIcon
                                                        style={{ marginTop: 8 }}
                                                    />
                                                )}
                                            </Space>
                                        }
                                    />
                                </List.Item>
                            )}
                        />
                    </Card>
                ) : (
                    <Alert message="Full Compliance" description={`No violations found for ${standardName} standard in the provided project.`} type="success" showIcon />
                )}
            </Space>
        );
    };

    const renderResults = () => {
        if (!results) return null;

        const reportStandards = results.standards || {};
        const standardKeys = Object.keys(reportStandards);

        if (standardKeys.length === 0) return <Alert message="No Data" description="The analyzer couldn't find any compliance data in the response." type="warning" showIcon />;

        const tabItems = standardKeys.map(key => {
            // If the key is too long (e.g. a rule description), truncate it for the tab label
            const label = key.length > 20 ? `${key.substring(0, 20)}...` : key;
            return {
                key,
                label: <span title={key}>{label}</span>,
                children: renderStandardReport(key, reportStandards[key])
            };
        });

        return (
            <Card title="Compliance Analysis Report" className={`shadow-md ${isDarkMode ? 'bg-gray-900 border-gray-800' : ''}`}>
                {results.summary && (
                    <Row gutter={16} className="mb-6">
                        <Col span={24}>
                            <div className={`p-4 rounded-lg mb-4 flex justify-between items-center ${isDarkMode ? 'bg-blue-900/20 border border-blue-800' : 'bg-blue-50 border border-blue-100'}`}>
                                <Space align="center">
                                    <div className="text-2xl text-blue-500"><SafetyCertificateOutlined /></div>
                                    <div>
                                        <Title level={4} style={{ margin: 0, color: isDarkMode ? '#e5e7eb' : '#1e3a8a' }}>Executive Summary</Title>
                                        <Text type="secondary">Security Posture Assessment</Text>
                                    </div>
                                </Space>
                                <Space size="large">
                                    <Statistic
                                        title={<Text type="secondary">Total Violations</Text>}
                                        value={results.summary.total_violations}
                                        valueStyle={{ color: '#cf1322', fontWeight: 'bold' }}
                                    />
                                    <div className="text-center">
                                        <Text type="secondary" className="block text-xs mb-1">Overall Grade</Text>
                                        <Tag
                                            color={results.summary.overall_score === 'A' ? 'success' : results.summary.overall_score === 'B' ? 'processing' : 'warning'}
                                            style={{ fontSize: '18px', padding: '4px 12px', height: 'auto', fontWeight: 'bold' }}
                                        >
                                            {results.summary.overall_score}
                                        </Tag>
                                    </div>
                                </Space>
                            </div>
                        </Col>
                    </Row>
                )}
                <Tabs
                    items={tabItems}
                    defaultActiveKey={standardKeys[0]}
                    type="card"
                    className="compliance-tabs"
                />
            </Card>
        );
    };

    const { isDarkMode } = useTheme();

    const standardsInfo = [
        { name: 'AWS CIS', desc: 'Secure benchmark for AWS resources.', color: 'blue' },
        { name: 'PCI DSS', desc: 'Payment card industry security.', color: 'purple' },
        { name: 'HIPAA', desc: 'Healthcare data privacy & security.', color: 'green' },
        { name: 'NIST', desc: 'Cybersecurity framework (800-53).', color: 'orange' },
        { name: 'GDPR', desc: 'EU data protection & privacy.', color: 'red' },
    ];

    return (
        <Space direction="vertical" size="large" style={{ width: '100%' }}>
            <Card title={<Space><SafetyCertificateOutlined className="text-green-500" /> Advanced Multi-Compliance Auditor</Space>}>
                <Paragraph type="secondary">Upload your Terraform modules (ZIP) to run deep security audits across multiple frameworks.</Paragraph>

                <div className="mb-6">
                    <Text strong className={`block mb-3 ${isDarkMode ? 'text-gray-300' : 'text-gray-600'}`}>Standard Frameworks:</Text>
                    <div className="flex flex-wrap gap-2">
                        {standardsInfo.map(s => (
                            <div key={s.name} className={`px-4 py-2 rounded-lg border flex-1 text-center min-w-[120px] ${isDarkMode ? 'border-gray-700 bg-gray-800' : 'border-gray-200 bg-gray-50'}`}>
                                <Tag color={s.color} className="m-0 text-sm">{s.name}</Tag>
                            </div>
                        ))}
                    </div>
                </div>

                <Title level={5}>Project Selection</Title>
                <div className="mb-6">
                    <Dragger
                        accept=".zip"
                        beforeUpload={(file) => {
                            handleFileUpload({ file });
                            return false;
                        }}
                        showUploadList={false}
                        className={`rounded-lg overflow-hidden transition-all ${isDarkMode ? 'bg-gray-800/50 border-gray-600 hover:border-blue-500' : 'bg-gray-50 border-gray-300 hover:border-blue-500'}`}
                        style={{ padding: '40px 20px' }}
                    >
                        <p className="ant-upload-drag-icon">
                            <FileZipOutlined style={{ fontSize: '48px', color: '#52c41a' }} />
                        </p>
                        <p className="ant-upload-text font-medium">{fileName ? `Selected: ${fileName}` : 'Click or drag Terraform ZIP to this area'}</p>
                        <p className="ant-upload-hint">Upload modules as a compressed archive for cross-module analysis.</p>
                    </Dragger>
                </div>

                <Row gutter={16} align="middle">
                    <Col xs={24} md={18} className="mb-4 md:mb-0">
                        <Select
                            mode="multiple"
                            placeholder="Select Compliance Standards"
                            style={{ width: '100%' }}
                            onChange={setSelectedStandards}
                            value={selectedStandards}
                            className="w-full"
                        >
                            {['AWS CIS', 'PCI DSS', 'HIPAA', 'NIST', 'GDPR'].map(s => <Select.Option key={s} value={s}>{s}</Select.Option>)}
                        </Select>
                    </Col>
                    <Col xs={24} md={6}>
                        <Button
                            type="primary"
                            icon={<SafetyCertificateOutlined />}
                            onClick={handleCheck}
                            loading={loading}
                            disabled={!zipBase64 || selectedStandards.length === 0}
                            block
                            size="large"
                        >
                            Run Audit
                        </Button>
                    </Col>
                </Row>
            </Card>
            <div id="results-area">
                {renderResults()}
            </div>
        </Space>
    );
};

export default ComplianceChecker;

import React, { useState } from 'react';
import { Card, Upload, Button, Typography, Space, message, Image, Row, Col } from 'antd';
import { CloudServerOutlined, UploadOutlined, CopyOutlined, RobotOutlined, FileTextOutlined, ArrowRightOutlined, DownloadOutlined } from '@ant-design/icons';
import { API_ENDPOINTS } from '../../../config/api';
import { useTheme } from '../../../contexts/ThemeContext';

const { Paragraph, Title, Text } = Typography;
const { Dragger } = Upload;

const ImageToTerraform: React.FC = () => {
    const [fileList, setFileList] = useState<any[]>([]);
    const [output, setOutput] = useState('');
    const [loading, setLoading] = useState(false);
    const [preview, setPreview] = useState('');
    const { isDarkMode } = useTheme();

    const [zipData, setZipData] = useState<string | null>(null);

    const handleUpload = async (options: any) => {
        const { file, onSuccess } = options;
        setFileList([file]);

        // Create preview
        const reader = new FileReader();
        reader.readAsDataURL(file);
        reader.onload = () => setPreview(reader.result as string);

        // Simulate upload success for UI
        setTimeout(() => onSuccess("ok"), 0);
    };

    const handleGenerate = async () => {
        if (fileList.length === 0) return;
        setLoading(true);
        setZipData(null);
        setOutput('');
        const formData = new FormData();
        formData.append('image', fileList[0]);

        try {
            const response = await fetch(API_ENDPOINTS.IMAGE_TO_TERRAFORM, {
                method: 'POST',
                body: formData,
            });
            const data = await response.json();

            if (data.zip_file) {
                setZipData(data.zip_file);
                setOutput(`✅ Success! Generated ${data.file_count} Terraform modules.\n\n⬇️ Click the "Download ZIP" button below to save the project files.`);
                message.success('Modules generated successfully!');
            } else if (data.terraform_code) {
                setOutput(data.terraform_code);
                message.success('Code generated successfully!');
            } else {
                setOutput(data.raw_output || data.message || 'No code generated.');
            }
        } catch (error) {
            console.error(error);
            message.error('Failed to process image.');
        } finally {
            setLoading(false);
        }
    };

    const handleDownloadZip = () => {
        if (!zipData) return;
        try {
            const binaryString = window.atob(zipData);
            const bytes = new Uint8Array(binaryString.length);
            for (let i = 0; i < binaryString.length; i++) {
                bytes[i] = binaryString.charCodeAt(i);
            }
            const blob = new Blob([bytes], { type: "application/zip" });
            const link = document.createElement('a');
            link.href = window.URL.createObjectURL(blob);
            link.download = "terraform_modules.zip";
            link.click();
            message.success('Download started');
        } catch (err) {
            console.error(err);
            message.error('Failed to download zip');
        }
    };

    return (
        <Space direction="vertical" size="large" style={{ width: '100%' }}>
            <Card title={<Space><CloudServerOutlined className="text-purple-500" /> Image to Terraform</Space>}>
                <Paragraph type="secondary">Upload an architecture diagram and get corresponding Terraform code.</Paragraph>

                <div className={`p-6 mb-6 rounded-lg border ${isDarkMode ? 'bg-gray-800 border-gray-700' : 'bg-blue-50 border-blue-100'}`}>
                    <Title level={5} className={`mb-4 ${isDarkMode ? 'text-gray-200' : 'text-blue-800'}`}>How it Works</Title>
                    <Row gutter={16} align="middle">
                        <Col span={7} className="text-center">
                            <div className={`text-3xl mb-2 ${isDarkMode ? 'text-blue-400' : 'text-blue-600'}`}><UploadOutlined /></div>
                            <Text className={isDarkMode ? 'text-gray-300' : ''}>1. Upload Diagram</Text>
                        </Col>
                        <Col span={1} className="text-center"><ArrowRightOutlined className="text-gray-400" /></Col>
                        <Col span={8} className="text-center">
                            <div className={`text-3xl mb-2 ${isDarkMode ? 'text-purple-400' : 'text-purple-600'}`}><RobotOutlined /></div>
                            <Text className={isDarkMode ? 'text-gray-300' : ''}>2. AI Analysis</Text>
                        </Col>
                        <Col span={1} className="text-center"><ArrowRightOutlined className="text-gray-400" /></Col>
                        <Col span={7} className="text-center">
                            <div className={`text-3xl mb-2 ${isDarkMode ? 'text-green-400' : 'text-green-600'}`}><FileTextOutlined /></div>
                            <Text className={isDarkMode ? 'text-gray-300' : ''}>3. Get Code</Text>
                        </Col>
                    </Row>
                </div>

                <Dragger
                    accept="image/*"
                    customRequest={handleUpload}
                    showUploadList={false}
                    className={`mb-6 border-dashed border-2 rounded-lg transition-colors ${isDarkMode
                        ? 'bg-gray-800 border-gray-600 hover:border-blue-500'
                        : 'bg-gray-50 border-gray-300 hover:border-blue-500'}`}
                >
                    <p className="ant-upload-drag-icon">
                        <UploadOutlined style={{ fontSize: '48px', color: '#1890ff' }} />
                    </p>
                    <p className="ant-upload-text">Click or drag file to this area to upload</p>
                    <p className="ant-upload-hint">Support for a single image upload.</p>
                </Dragger>

                {preview && (
                    <div className="mb-6 text-center">
                        <Image src={preview} height={200} className="rounded-lg shadow-md" />
                    </div>
                )}

                <Space size="middle" style={{ width: '100%', justifyContent: 'center' }}>
                    <Button
                        type="primary"
                        onClick={handleGenerate}
                        loading={loading}
                        disabled={fileList.length === 0}
                        size="large"
                    >
                        Generate Terraform Code
                    </Button>
                    <Button
                        icon={<DownloadOutlined />}
                        onClick={handleDownloadZip}
                        disabled={!zipData}
                        size="large"
                    >
                        Download ZIP
                    </Button>
                </Space>
            </Card>


            {output && (
                <Card
                    title="Generated Code"
                    extra={<Button icon={<CopyOutlined />} onClick={() => navigator.clipboard.writeText(output)}>Copy</Button>}
                >
                    <pre className="bg-gray-900 text-green-400 p-4 rounded-lg overflow-x-auto font-mono text-sm">
                        {output}
                    </pre>
                </Card>
            )}
        </Space>
    );
};

export default ImageToTerraform;

import React from 'react';
import { Layout, Menu, Typography, Avatar, Dropdown, Space, Button } from 'antd';
import {
